contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint value) public payable {
        require(msg.sender != c.owner());
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;
        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(
            (reverted && depositsAfter == depositsBefore) ||
            (!reverted && depositsAfter == depositsBefore && c.owner() != msg.sender && address(c).balance + value == balanceBefore)
        );
    }
}

